from collections import deque

def get_valid_time(hour, minute):
    if 0 <= hour <= 23 and 0 <= minute <= 59:
        return f"{hour:02}:{minute:02}"
    return None

def bfs(start_time, end_time):
    queue = deque([(start_time, [start_time])])
    visited = set([start_time])

    while queue:
        current_time, path = queue.popleft()

        if current_time == end_time:
            return path

        current_hour = int(current_time[:2])
        current_minute = int(current_time[3:])

        # Possible changes: +1 or -1 for each digit
        changes = [
            (current_hour + 1) % 24, (current_hour - 1) % 24,
            (current_minute + 1) % 60, (current_minute - 1) % 60
        ]

        for i in range(2):
            new_hour = changes[i]
            new_time = get_valid_time(new_hour, current_minute)
            if new_time and new_time not in visited:
                visited.add(new_time)
                queue.append((new_time, path + [new_time]))

        for i in range(2, 4):
            new_minute = changes[i]
            new_time = get_valid_time(current_hour, new_minute)
            if new_time and new_time not in visited:
                visited.add(new_time)
                queue.append((new_time, path + [new_time]))

